-- ========================================================================

-- Audit trail of every classification rule that fired during grading. Each row
-- records one rule firing with the pathway stage it concerns, the category, and
-- a human-readable description.

CREATE TABLE diabetic_eye_screening_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    diabetic_eye_screening_grade_id UUID NOT NULL
        REFERENCES diabetic_eye_screening_grade(id) ON DELETE CASCADE,

    rule_id VARCHAR(40) NOT NULL,
    stage VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (stage IN ('eligibility', 'retinopathy', 'maculopathy', 'ungradable', 'recall', 'completeness', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX diabetic_eye_screening_grade_rule_grade_id_idx
    ON diabetic_eye_screening_grade_rule (diabetic_eye_screening_grade_id);

CREATE TRIGGER trigger_diabetic_eye_screening_grade_rule_updated_at
    BEFORE UPDATE ON diabetic_eye_screening_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE diabetic_eye_screening_grade_rule IS
    'Audit trail of every classification rule that fired during grading: pathway stage, category, and description.';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.created_at IS
    'Timestamp when the row was created.';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.updated_at IS
    'Timestamp when the row was most recently updated.';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.diabetic_eye_screening_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.rule_id IS
    'Stable rule identifier (e.g. R-RECALL-R3A-01).';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.stage IS
    'Pathway stage the rule concerns: eligibility, retinopathy, maculopathy, ungradable, recall, or completeness.';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.category IS
    'Subject category (e.g. gate, classification, conditional-requirement).';
COMMENT ON COLUMN diabetic_eye_screening_grade_rule.description IS
    'Human-readable description of why the rule fired.';

-- ========================================================================
-- END 06_create_table_diabetic_eye_screening_grade_rule.sql
